<script lang="ts">
  import {gameState} from '../../stores/gameStore.svelte';
  import {showToast} from '../../stores/uiStore.svelte';
  import {HOME_DECOR_CATALOG,setHomeDecor,type HomeSurface} from '../../game/core/homeDecor';
  import {formalHomeId} from '../../game/core/homeInterior';
  let {onClose}:{onClose:()=>void}=$props();
  const address=$derived(formalHomeId(gameState)??'old_apartment');
  function apply(surface:HomeSurface,id?:string){const r=setHomeDecor(gameState,surface,id);if(!r.ok)showToast(r.reason??'暂时不能更换');}
</script>
<div class="home-decor-panel" role="dialog" aria-label="墙面与地面">
  <header><div><small>给家换个样子</small><h3>墙面与地面</h3></div><button aria-label="收起装修面板" onclick={onClose}>×</button></header>
  <p>在家居店买下喜欢的材料。已购买的样式可反复更换，每个住处单独保存。</p>
  {#each [{surface:'wall',name:'墙面'},{surface:'floor',name:'起居地面'}] as group}<div class="surface-section"><h4>{group.name}</h4><div class="surface-choices">
    <button class:chosen={!gameState.homeDecor?.[address]?.[group.surface as HomeSurface]} onclick={()=>apply(group.surface as HomeSurface)} data-home-finish={`${group.surface}:default`}><span class="default-swatch">↺</span><span>房源原装<small>恢复这处住所的原始装修</small></span></button>
    {#each HOME_DECOR_CATALOG.filter(c=>c.surface===group.surface) as style}{@const owned=(gameState.inventory[style.id]??0)>0}<button class:chosen={gameState.homeDecor?.[address]?.[group.surface as HomeSurface]===style.id} disabled={!owned} onclick={()=>apply(style.surface,style.id)} data-home-finish={style.id}><span class="surface-swatch" data-pattern={style.pattern} style:--surface-color={style.color} style:--surface-detail={style.detail}></span><span>{style.name}<small>{owned?'已购买 · 点击更换':'在家居店购买'}</small></span></button>{/each}
  </div></div>{/each}
  <p class="wet-note">浴室等湿区保留防水地面。更换样式不消耗时间和金钱。</p>
</div>
