ackground-color:var(--surface-color);background-image:linear-gradient(0deg,transparent 94%,var(--surface-detail) 94%),linear-gradient(90deg,transparent 94%,var(--surface-detail) 94%);background-size:16px 16px}.wet-note{margin-bottom:0;font-size:10px}
